-- 20270130000003_institutional_decisions.sql
--
-- PR-05 (Escalation + SLA) + PR-06 (Decision Engine) + PR-07 (Delegation
-- Engine). One migration because they are one institutional loop:
--
--   case → policy/authority → escalation (when refused / SLA-breached)
--        → decision (the durable approve/reject record)
--        → delegation (the bounded grant that may have produced it)
--        → audit
--
-- PR-05 · escalations + sla_instances: when an authority check is refused
--      (bounds exceeded) or an SLA is breached, an escalation row is
--      generated BY POLICY (not by frontend code) carrying an explicit
--      reason (PR-01 EscalationReason). The Executive Attention Engine
--      (PR-09) consumes these.
--
-- PR-06 · decisions + decision_signatures: the durable decision record
--      (actor, role_context, authority, reason, evidence, impact,
--      timestamp, signature). Every consequential action — approve,
--      reject, revoke, suspend, debar, override — becomes this. The
--      case layer's state only changes through a decision; decisions are
--      the institutional decision history.
--
-- PR-07 · delegations is already in entity_foundation (20270115000001);
--      this PR adds nothing to it — the delegation engine is the query
--      pattern (delegation-aware authority matching) that PR-04's
--      authorize() already runs. We record here, not re-implement.
--
-- Compose, don't fork:
--   * escalations.case_id → cases.id (PR-02); authority_ids jsonb cites
--     authority_policies.id (PR-04)
--   * decisions.case_id → cases.id; decisions.authority_source mirrors
--     the PR-04 AuthorityDecision shape
--   * decision_signatures links a decision to the credential that signed
--     it (an audit_events.id / a JWT id / a document-signature id) so
--     PR-11 can reconstruct "who signed, under what authority"
--
-- Idempotent: IF NOT EXISTS / ON CONFLICT everywhere; re-runs are no-ops.
-- Rollback: .down.sql drops in reverse dependency order.

BEGIN;

-- ============================================================
-- PR-05 · 1. escalations — generated by policy, not frontend code
-- ============================================================
CREATE TABLE IF NOT EXISTS public.escalations (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  case_id        UUID NOT NULL REFERENCES public.cases(id) ON DELETE CASCADE,
  -- The PR-01 EscalationReason enum: SLA_BREACH | RISK_INCREASE |
  -- AUTHORITY_INSUFFICIENT | HIGH_IMPACT | REPEATED_REJECTION |
  -- CROSS_DOMAIN | MANUAL | EMERGENCY | POLICY_REQUIRED |
  -- CONFLICT_OF_INTEREST. Stored so the principal sees WHY, not just
  -- "new request".
  reason         TEXT NOT NULL,
  severity       TEXT NOT NULL DEFAULT 'MEDIUM'
                 CHECK (severity IN ('LOW','MEDIUM','HIGH','CRITICAL')),
  -- The source that generated this escalation (an authority refusal,
  -- an SLA breach, a risk jump). Free text: 'authority_refused:<policy>'
  -- | 'sla_breach:<sla_instance_id>' | 'manual:<user_id>'.
  source         TEXT,
  -- The role / context the escalation targets. NULL = the domain ladder
  -- (escalation-ladder.ts LADDER) decides.
  target_role    TEXT,
  target_context TEXT,
  -- The authority ids that were considered (and why they failed).
  authority_ids  JSONB NOT NULL DEFAULT '[]'::jsonb,
  deadline       TIMESTAMPTZ,
  -- Structured evidence the escalation carries (case refs, the bounds
  -- that were exceeded, the repeated-rejection count).
  evidence       JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- The recommended action the system proposes (PR-09 surfaces it).
  recommended_action TEXT,
  status         TEXT NOT NULL DEFAULT 'OPEN'
                 CHECK (status IN ('OPEN','RESOLVED','DISMISSED')),
  resolved_by    UUID REFERENCES public.users(id),
  resolved_at    TIMESTAMPTZ,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_escalations_case    ON public.escalations (case_id);
CREATE INDEX IF NOT EXISTS idx_escalations_open    ON public.escalations (status, severity DESC) WHERE status = 'OPEN';
CREATE INDEX IF NOT EXISTS idx_escalations_target  ON public.escalations (target_role, status) WHERE status = 'OPEN';

GRANT SELECT, INSERT, UPDATE ON public.escalations TO gate_app, admin, authenticated;
GRANT UPDATE, DELETE ON public.escalations TO admin;

-- ============================================================
-- PR-05 · 2. sla_instances — the SLA that an escalation can breach
-- ============================================================
CREATE TABLE IF NOT EXISTS public.sla_instances (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  case_id        UUID NOT NULL REFERENCES public.cases(id) ON DELETE CASCADE,
  -- The SLA rule that started the clock (a policy_rules.code or a
  -- domain-specific SLA key). Free text: the engine reads the rule,
  -- the instance records the deadline.
  sla_rule       TEXT NOT NULL,
  started_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  due_at         TIMESTAMPTZ NOT NULL,
  -- True when the clock has been reset (a re-escalation, a new stage).
  extended_to    TIMESTAMPTZ,
  status         TEXT NOT NULL DEFAULT 'RUNNING'
                 CHECK (status IN ('RUNNING','MET','BREACHED')),
  met_at         TIMESTAMPTZ,
  breached_at    TIMESTAMPTZ,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_sla_case    ON public.sla_instances (case_id);
CREATE INDEX IF NOT EXISTS idx_sla_due     ON public.sla_instances (due_at) WHERE status = 'RUNNING';

GRANT SELECT, INSERT, UPDATE ON public.sla_instances TO gate_app, admin, authenticated;
GRANT UPDATE, DELETE ON public.sla_instances TO admin;

-- ============================================================
-- PR-06 · 1. decisions — the durable institutional decision record
-- ============================================================
CREATE TABLE IF NOT EXISTS public.decisions (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  -- Human key, e.g. 'DEC-2026-0421' (correlation across the chain).
  decision_no    TEXT UNIQUE,
  case_id        UUID NOT NULL REFERENCES public.cases(id) ON DELETE CASCADE,
  -- The PR-01 StandardOperation (approve / reject / revoke / suspend /
  -- debar / override / escalate / delegate / lockdown).
  operation      TEXT NOT NULL,
  -- Who + under which hat + by what authority (mirrors AuthorityDecision).
  actor_id       UUID NOT NULL REFERENCES public.users(id),
  actor_role     TEXT NOT NULL,
  role_context   TEXT NOT NULL DEFAULT 'administrative',
  authority_source TEXT NOT NULL DEFAULT 'role'
                 CHECK (authority_source IN ('role','delegation','emergency_override')),
  -- The specific authority_policies.id that allowed this (empty = engine
  -- default / emergency override). JSONB: a decision may cite several.
  authority_ids  JSONB NOT NULL DEFAULT '[]'::jsonb,
  -- When authority_source = 'delegation', the delegations.id that
  -- satisfied it (the grant's scope + window bound the decision).
  delegation_id  UUID,
  -- The structured reason (never just "approved" — why, per the case).
  reason         TEXT NOT NULL,
  -- Evidence attached (case refs, the impact preview, the prior state).
  evidence       JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- The impact preview computed BEFORE execution (PR-08 fills this in;
  -- until then it is the decision's own effect summary).
  impact         JSONB NOT NULL DEFAULT '[]'::jsonb,
  -- The state the case was in before / after this decision.
  previous_state TEXT,
  resulting_state TEXT,
  timestamp      TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_decisions_case      ON public.decisions (case_id, timestamp DESC);
CREATE INDEX IF NOT EXISTS idx_decisions_actor     ON public.decisions (actor_id, timestamp DESC);
CREATE INDEX IF NOT EXISTS idx_decisions_operation ON public.decisions (operation, timestamp DESC);
CREATE INDEX IF NOT EXISTS idx_decisions_authority ON public.decisions (authority_source);

GRANT SELECT, INSERT ON public.decisions TO gate_app, admin, authenticated;
GRANT UPDATE, DELETE ON public.decisions TO admin;

-- ============================================================
-- PR-06 · 2. decision_signatures — the credential that signed it
-- ============================================================
CREATE TABLE IF NOT EXISTS public.decision_signatures (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  decision_id    UUID NOT NULL REFERENCES public.decisions(id) ON DELETE CASCADE,
  -- What signed: an audit_events.event_id, a document-signature id,
  -- a JWT credential id, or 'system' for automated (kill-switch gated)
  -- executions. The signature is the proof, not the assertion.
  signature_kind TEXT NOT NULL,
  signature_ref  TEXT NOT NULL,
  signed_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_decision_sigs_decision ON public.decision_signatures (decision_id);

GRANT SELECT, INSERT ON public.decision_signatures TO gate_app, admin, authenticated;
GRANT UPDATE, DELETE ON public.decision_signatures TO admin;

-- ============================================================
-- PR-07 · delegation: no new table — the engine is the query
-- ============================================================
-- The delegation engine is PR-04's delegation-aware authorize(): an
-- active, unrevoked, in-window `delegations` row (entity_foundation)
-- satisfies an authority policy that requires a role the delegatee does
-- not directly hold. We do NOT add a parallel delegation table here;
-- the bounded grant already lives in `delegations` and the matching
-- already runs in `authorize()`. This comment is the PR-07 evidence:
-- the delegation engine is the pattern, not the schema.

COMMIT;
